INSERT INTO Language_ko_KR (Tag, Text)
VALUES	('TXT_KEY_BUILDING_PIPELINE',			'파이프라인'),
		('TXT_KEY_BUILDING_PIPELINE_TEXT',		'원유와 정제된 석유, 석유, 천연가스, 바이오연료와 같은 연료, 하수, 슬러리, 물, 맥주, 짧은 거리의 뜨거운 물이나 증기를 수송하기 위한 파이프라인이 존재하며, 유용한 작업과 고체 물체를 운반하기 위한 흡입 압력을 생성할 수 있는 공압 시스템도 존재합니다. 이전의 송수로와 마찬가지로 파이프라인은 언덕을 넘어야 할 때나 증발, 오염 또는 환경에 미치는 영향으로 인해 운하나 수로를 사용하는 것이 적합하지 않은 경우, 식수나 관개용수를 장거리로 운반하는 데 유용합니다.[NEWLINE][NEWLINE]파이프라인은 도로나 철도에 비해 물질을 운반하는 가장 안전한 방법 중 하나이므로 전쟁에서는 파이프라인이 군사적 공격의 표적이 되는 경우가 많습니다. 실제로 미국에서는 원유와 석유 제품의 70%가 파이프라인을 통해 운송됩니다. (23%는 선박, 4%는 화물차, 3%는 철도) 캐나다에서는 천연가스와 석유 제품의 97%가 파이프라인을 통해 운송됩니다.'),
		('TXT_KEY_BUILDING_PIPELINE_STRATEGY',	'파이프라인은 문명 전역의 석유 가치를 높여주는 원자력 시대 건물입니다. 구체적으로 말하면, 골드와 국경 성장 점수를 제공하는데, 이는 파이프라인의 국경 확장 보너스와 결합되어 석유 생산 도시의 생산성을 크게 높여줍니다. 이 방법은 도시가 비교적 새로 생겼을 때 특히 효과적인데 도시의 경계가 훨씬 더 쉽게 확장될 수 있기 때문입니다! 하지만 파이프라인의 힘을 활용하려면 먼저 산업 도시 연결을 구축해야 합니다.'),
		('TXT_KEY_BUILDING_PIPELINE_HELP',		'도시의 경계가 확장되면 [ICON_PRODUCTION] 생산력과 [ICON_RESEARCH] 과학이 20 증가합니다. (시대에 따라 보정) [ICON_INDUSTRIAL_CONNECTED] 지역 도시와의 연결로 인해 [ICON_GOLD] 골드와 [ICON_PRODUCTION] 생산력이 +50% 증가합니다. 이 도시의 내부 [ICON_INTERNATIONAL_TRADE] 교역로는 [ICON_PRODUCTION] 생산력 +6을 생성합니다.[NEWLINE][NEWLINE]문명 내 모든 [ICON_RES_OIL] 석유의 [ICON_PRODUCTION] 생산력, [ICON_GOLD] 골드, [ICON_CULTURE_LOCAL] 국경 성장 점수가 +2 증가합니다.[NEWLINE][NEWLINE]건설하려면 인근에 [ICON_RES_OIL] 석유 자원과 [ICON_INDUSTRIAL_CONNECTED] 산업 도시 연결이 필요합니다.');